import test from 'node:test';import assert from 'node:assert/strict';import {correctProductData} from './product-title-corrections.mjs';
test('triagem96 nao autentica nem prescreve ou inventa relatos e preserva operacao',()=>{for(const [id,titulo] of [['mlMLB4151024813','Tênis Mizuno Nirvana 9 Leve Caminhada Academia Treino'],['mlMLB4231915505','Controle Joystick Wireless Compatível C/ Pc Android N-switch'],['mlMLB4291652941','CÚRCUMA 130mg + COLÁGENO Tipo II 45mg - Fórmula com Máxima Concentração e Pureza - 60 Cápsulas']]){const p={id,titulo,preco:'preservar',linkAfiliado:'https://meli.la/preservar'},x=correctProductData(p);assert.equal(x.preco,p.preco);assert.equal(x.linkAfiliado,p.linkAfiliado);assert.deepEqual(correctProductData(x),x);assert.equal(correctProductData({...p,titulo:'Outro produto',comentario:'manter'}).comentario,'manter');assert.doesNotMatch(x.pros,/pureza comprovada|excelente avaliação|longevidade articular|catálogo confirmado/i);if(id==='mlMLB4291652941')assert.doesNotMatch(x.titulo,/Máxima|Pureza/);}});
